opts={'A':48,'B':72,'C':54,'D':70}
f=lambda n:n*n-9
assert f(7)==40 and f(5)==16
fit=[k for k,v in opts.items() if v==f(9)]
assert fit==['B']
for k in 'ACD': assert opts[k]!=f(9)

s='B_DE_GDGBK_IB_DK'
opts={'A':'CBDP','B':'OCBD','C':'CODB','D':'CBDO'}
def ok(fill):
    it=iter(fill); t=''.join(next(it) if c=='_' else c for c in s)
    g=[t[i:i+4] for i in range(0,16,4)]
    return all(x[0]=='B' and x[2]=='D' for x in g) and all(ord(g[i+1][1])-ord(g[i][1])==4 and ord(g[i+1][3])-ord(g[i][3])==2 for i in range(3))
assert [k for k,v in opts.items() if ok(v)]==['D']

par={'Q':'S','T':'Q','P':'Q'}
gender={'Q':'F','P':'F','S':'M','R':'M','T':'M'}
def rel(x,y):
    p=par.get(x); gp=par.get(p) if p else None
    if gp==y: return ('Daughter' if gender[p]=='F' else 'Son')+'’s '+('daughter' if gender[x]=='F' else 'son')
opts={'A':'Daughter’s daughter','B':'Mother’s father','C':'Brother’s wife','D':'Mother’s mother'}
assert [k for k,v in opts.items() if v==rel('P','S')]==['A']

import itertools
opp=None
# cycle around top face 2 must contain 1->3 and 5->4 as consecutive clockwise pairs
for perm in itertools.permutations([3,5,4]):
    cyc=[1]+list(perm)
    nxt={cyc[i]:cyc[(i+1)%4] for i in range(4)}
    if nxt[1]==3 and nxt[5]==4:
        opp={cyc[i]:cyc[(i+2)%4] for i in range(4)}[5]
opts={'A':3,'B':2,'C':1,'D':6}
assert [k for k,v in opts.items() if v==opp]==['C']

